<template><div class="filter-builder"><div v-for="(rule,index) in modelValue" :key="rule.id" class="filter-rule"><span v-if="index" class="filter-rule__join">且</span><select :value="rule.field" @change="patch(rule.id,'field',$event)"><option v-for="field in fields" :key="field.value" :value="field.value">{{field.label}}</option></select><select :value="rule.operator" @change="patch(rule.id,'operator',$event)"><option v-for="operator in operators" :key="operator.value" :value="operator.value">{{operator.label}}</option></select><input :value="rule.value" placeholder="输入值" @input="patch(rule.id,'value',$event)"/><button type="button" aria-label="删除条件" @click="remove(rule.id)">×</button></div><button class="filter-add" type="button" @click="add">＋ 添加条件</button></div></template>
<script setup lang="ts">import type{LnFilterRule,LnOption}from'./types';const props=withDefaults(defineProps<{modelValue:LnFilterRule[];fields:LnOption[];operators?:LnOption[]}>(),{operators:()=>[{label:'等于',value:'eq'},{label:'不等于',value:'neq'},{label:'包含',value:'contains'}]});const emit=defineEmits<{(e:'update:modelValue',value:LnFilterRule[]):void}>();function patch(id:string,key:keyof LnFilterRule,event:Event){const value=(event.target as HTMLInputElement).value;emit('update:modelValue',props.modelValue.map(r=>r.id===id?{...r,[key]:value}:r))}function remove(id:string){emit('update:modelValue',props.modelValue.filter(r=>r.id!==id))}function add(){emit('update:modelValue',[...props.modelValue,{id:`filter-${Date.now()}`,field:props.fields[0]?.value||'',operator:props.operators[0]?.value||'eq',value:''}])}</script>
<style scoped lang="scss">
.filter-builder{display:grid;gap:7px;font-family:var(--ln-font)}.filter-rule{display:flex;align-items:center;gap:5px}.filter-rule__join{width:22px;color:var(--ln-text-tertiary);font-size:10px;text-align:center}.filter-rule select,.filter-rule input{height:30px;padding:0 8px;border:1px solid var(--ln-border);border-radius:6px;background:var(--ln-surface);color:var(--ln-text);outline:0;font:12px var(--ln-font);&:focus{border-color:var(--ln-accent);box-shadow:0 0 0 2px var(--ln-accent-soft)}}.filter-rule input{min-width:90px;flex:1}.filter-rule button{width:26px;height:26px;border:0;border-radius:5px;background:transparent;color:var(--ln-text-tertiary);cursor:pointer;&:hover{background:var(--ln-surface-hover);color:var(--ln-danger)}}.filter-add{width:max-content;padding:6px 8px;border:0;border-radius:5px;background:transparent;color:var(--ln-text-secondary);font:12px var(--ln-font);cursor:pointer;&:hover{background:var(--ln-surface-hover);color:var(--ln-text)}}
</style>
